style.ifMode:
form input[type="radio"], .form input[type="radio"] {
    float: none;
    display: inline-block;
}

p.radio :is(input, label) {
    display: inline;
    float: none !important;
    min-width: initial;
}

.flex-questions {
    display: flex;
    flex-wrap: wrap;
}

.flex-questions > div {
    margin-right: 16px;
    margin-bottom: 8px;
}

form fieldset {
    min-width: 90%;
    display: block;
}

.cb-align input[type=checkbox] {
    margin: 0px 5px;
    top:0px;
}

.family-history-item .label {
    display: inline-block;
    width: 250px;
}
.family-history-item .relative {
    display: inline-block;
    width: 120px;
}

.past-medical-history-item input[type=checkbox] {
    float: none;
    vertical-align: middle;
}

.past-medical-history-item input[type=text] {
    min-width: 200px;
    display: inline !important;
    vertical-align: middle;
    padding: 1px 10px;
}

.past-medical-history-item > span, .past-medical-history-item > label {
    display: inline !important;
    vertical-align: middle;
}

.small-input input {
    min-width: 12em;
    width: 12em;
}

ifMode.script:
jq(function() {
    var encounterDate = '';
    setUpEdd(encounterDate, '');
    validateEstimatedDeliveryDate("edd", new Date(+encounterDate), '');
    eddCannotBeOlderThanTwoWeeks("edd", new Date(+encounterDate), '');
    setUpExpandableContacts('');
    setUpDatepickerStartAndEndDateValidation();
    setUpObsWithObsDateTime('syph-checkbox');

    // handlers for next and submit buttons, see nextAndSubmitButtons.js
    setUpNextAndSubmitButtons();
    manageInputActivationForRadioButton("#Isoniazide","#treatmentLine",["#inhStartDate","#inhEndDate"],["#inhStartDate"],'')
    updateLastCheckboxRequired("#transmission","#trans-required-msg",'')
});
